import{_ as t,o,c as a,ai as n}from"./chunks/framework.jD4ETUAz.js";const u=JSON.parse('{"title":"Download annual reports of Chinese listed companies","description":"Three ways to get A-share annual reports as PDF: download from CNINFO by hand, have an AI assistant fetch every year with cninfo-mcp, or read without saving.","frontmatter":{"title":"Download annual reports of Chinese listed companies","description":"Three ways to get A-share annual reports as PDF: download from CNINFO by hand, have an AI assistant fetch every year with cninfo-mcp, or read without saving.","article":true,"date":"2026-11-16T00:00:00.000Z","editLink":false,"translation":"guides/download-annual-reports.md","head":[["link",{"rel":"canonical","href":"https://youhaozhao.github.io/cninfo-mcp/en/guides/download-annual-reports"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"cninfo-mcp"}],["meta",{"property":"og:title","content":"Download annual reports of Chinese listed companies | cninfo-mcp"}],["meta",{"property":"og:description","content":"Three ways to get A-share annual reports as PDF: download from CNINFO by hand, have an AI assistant fetch every year with cninfo-mcp, or read without saving."}],["meta",{"property":"og:url","content":"https://youhaozhao.github.io/cninfo-mcp/en/guides/download-annual-reports"}],["meta",{"property":"og:image","content":"https://youhaozhao.github.io/cninfo-mcp/og-en.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Download annual reports of Chinese listed companies | cninfo-mcp"}],["meta",{"name":"twitter:description","content":"Three ways to get A-share annual reports as PDF: download from CNINFO by hand, have an AI assistant fetch every year with cninfo-mcp, or read without saving."}],["meta",{"name":"twitter:image","content":"https://youhaozhao.github.io/cninfo-mcp/og-en.png"}],["link",{"rel":"alternate","hreflang":"zh","href":"https://youhaozhao.github.io/cninfo-mcp/guides/download-annual-reports"}],["link",{"rel":"alternate","hreflang":"en","href":"https://youhaozhao.github.io/cninfo-mcp/en/guides/download-annual-reports"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://youhaozhao.github.io/cninfo-mcp/en/guides/download-annual-reports"}],["meta",{"property":"og:locale:alternate","content":"zh_CN"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Guides\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/guides/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"Download annual reports of Chinese listed companies\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/guides/download-annual-reports\\"}]},{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/guides/download-annual-reports#article\\",\\"headline\\":\\"Download annual reports of Chinese listed companies\\",\\"description\\":\\"Three ways to get A-share annual reports as PDF: download from CNINFO by hand, have an AI assistant fetch every year with cninfo-mcp, or read without saving.\\",\\"inLanguage\\":\\"en\\",\\"url\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/guides/download-annual-reports\\",\\"mainEntityOfPage\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/guides/download-annual-reports\\",\\"image\\":\\"https://youhaozhao.github.io/cninfo-mcp/og-en.png\\",\\"datePublished\\":\\"2026-11-16T00:00:00.000Z\\",\\"dateModified\\":\\"2026-11-16T07:46:57.000Z\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"youhaozhao\\",\\"url\\":\\"https://github.com/youhaozhao\\"},\\"publisher\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"youhaozhao\\",\\"url\\":\\"https://github.com/youhaozhao\\"},\\"isPartOf\\":{\\"@id\\":\\"https://youhaozhao.github.io/cninfo-mcp/#website\\"},\\"about\\":{\\"@id\\":\\"https://youhaozhao.github.io/cninfo-mcp/#software\\"}}]}"]]},"headers":[],"relativePath":"en/guides/download-annual-reports.md","filePath":"en/guides/download-annual-reports.md","lastUpdated":1794815217000}'),r={name:"en/guides/download-annual-reports.md"};function i(s,e,d,l,h,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="download-annual-reports-of-chinese-listed-companies" tabindex="-1">Download annual reports of Chinese listed companies <a class="header-anchor" href="#download-annual-reports-of-chinese-listed-companies" aria-label="Permalink to &quot;Download annual reports of Chinese listed companies&quot;">​</a></h1><p>Annual, semi-annual and quarterly reports of companies listed in Shanghai, Shenzhen and Beijing are published on CNINFO (cninfo.com.cn), the disclosure website designated by the China Securities Regulatory Commission, and are free to download. For a single report the website is enough. To collect every report a company has filed, or to have an AI assistant read as it downloads, cninfo-mcp is quicker.</p><h2 id="option-1-download-from-cninfo-by-hand" tabindex="-1">Option 1: download from CNINFO by hand <a class="header-anchor" href="#option-1-download-from-cninfo-by-hand" aria-label="Permalink to &quot;Option 1: download from CNINFO by hand&quot;">​</a></h2><ol><li>Open <a href="https://www.cninfo.com.cn" target="_blank" rel="noreferrer">cninfo.com.cn</a> and search for the stock code to open the company page.</li><li>Filter the announcement list by the category for annual reports (年报).</li><li>Open the report you need and download the PDF.</li></ol><p>The site is in Chinese, and the list mixes the full report with its summary, the English version if there is one, and correction notices, all with similar titles. For Kweichow Moutai&#39;s 2025 annual report, three documents were published on the same day:</p><table tabindex="0"><thead><tr><th>Title</th><th>What it is</th></tr></thead><tbody><tr><td>贵州茅台2025年年度报告</td><td>The full report, 143 pages</td></tr><tr><td>贵州茅台2025年年度报告摘要</td><td>The summary</td></tr><tr><td>贵州茅台2025年年度报告（英文版）</td><td>The English version</td></tr></tbody></table><h2 id="option-2-ask-your-ai-assistant" tabindex="-1">Option 2: ask your AI assistant <a class="header-anchor" href="#option-2-ask-your-ai-assistant" aria-label="Permalink to &quot;Option 2: ask your AI assistant&quot;">​</a></h2><p>With <a href="/cninfo-mcp/en/install">cninfo-mcp installed</a>, say what you want:</p><blockquote><p>Download the 2025 annual report of Kweichow Moutai (600519)</p></blockquote><blockquote><p>Download every annual report of 300750 into the folder catl/annual</p></blockquote><p>The assistant calls <code>download_reports</code>. What to expect:</p><ul><li><strong>Location</strong>: files go to <code>~/Downloads/cninfo-mcp</code> by default. Change it with the environment variable <code>CNINFO_MCP_DOWNLOAD_DIR</code>. A folder named in your request, such as <code>catl/annual</code>, is created inside that directory, and the tool never writes outside it.</li><li><strong>File names</strong>: <code>code_name_title_announcementID.pdf</code>, for example <code>600519_贵州茅台_贵州茅台2025年年度报告_1225114741.pdf</code>.</li><li><strong>Full reports only</strong>: summaries and English versions are left out. Revised full texts are included.</li><li><strong>No repeated downloads</strong>: files that already exist are skipped, so an interrupted run can simply be started again.</li><li><strong>No year means every year</strong>: for Kweichow Moutai that is 27 documents covering fiscal years 2001 to 2025.</li></ul><p>The result lists the path of every file. If a file fails, the others are still saved and the failure is reported separately.</p><h2 id="option-3-read-without-downloading" tabindex="-1">Option 3: read without downloading <a class="header-anchor" href="#option-3-read-without-downloading" aria-label="Permalink to &quot;Option 3: read without downloading&quot;">​</a></h2><p>If you only need the content, there is nothing to download. The assistant can read the PDF text directly with <code>read_document</code>:</p><blockquote><p>What is the profit distribution plan in the 2025 annual report of 600519? Cite the page.</p></blockquote><p>See <a href="/cninfo-mcp/en/guides/read-annual-reports-with-ai">Read Chinese annual reports with AI</a>.</p><h2 id="english-versions" tabindex="-1">English versions <a class="header-anchor" href="#english-versions" aria-label="Permalink to &quot;English versions&quot;">​</a></h2><p>Most companies file in Chinese only. Some also publish an English version of the annual report. To find it, ask for the list including variants:</p><blockquote><p>List the 2025 annual report of 600519 including summaries and English versions</p></blockquote><p><code>list_reports</code> then returns each document with a <code>kind</code> (<code>main</code>, <code>revised</code>, <code>summary</code>, <code>english</code>, <code>h_share</code>), and the assistant can download the English one by URL with <code>download_documents</code>.</p><h2 id="other-report-types" tabindex="-1">Other report types <a class="header-anchor" href="#other-report-types" aria-label="Permalink to &quot;Other report types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Report</th><th>Ask for</th></tr></thead><tbody><tr><td>Annual report</td><td>annual report</td></tr><tr><td>Semi-annual report</td><td>semi-annual or interim report</td></tr><tr><td>First-quarter report</td><td>Q1 report</td></tr><tr><td>Third-quarter report</td><td>Q3 report</td></tr><tr><td>IPO prospectus</td><td>prospectus</td></tr></tbody></table><p>A prospectus has no fiscal year, so leave the year out.</p><h2 id="several-companies" tabindex="-1">Several companies <a class="header-anchor" href="#several-companies" aria-label="Permalink to &quot;Several companies&quot;">​</a></h2><p><code>download_reports</code> handles one company per call. Name several companies in one request and the assistant calls the tool for each:</p><blockquote><p>Download the 2025 annual reports of 600519, 000858 and 000568, one folder per company</p></blockquote><div class="warning custom-block"><p class="custom-block-title">Keep the default concurrency</p><p>CNINFO answers bursts of requests with HTTP 403 and blocks the IP address for a while. cninfo-mcp rate-limits every request and backs off when throttled. It is meant for the reports your research needs, not for scraping the whole market.</p></div><p>If you need report text for the whole market over many years, for example for a text-analysis study, an official data service or a commercial database is the right source. See <a href="/cninfo-mcp/en/guides/cninfo-api">Is there a CNINFO API?</a>.</p><h2 id="reuse-and-redistribution" tabindex="-1">Reuse and redistribution <a class="header-anchor" href="#reuse-and-redistribution" aria-label="Permalink to &quot;Reuse and redistribution&quot;">​</a></h2><p>The reports are disclosed by the listed companies, and CNINFO&#39;s footer states that the site&#39;s content is copyrighted by Shenzhen Securities Information Co., Ltd. Whether you may redistribute downloaded files or use them commercially is for you to verify.</p>',31)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
